start:
DO $ddl_pre$ BEGIN
 IF current_user<>'postgres' OR (SELECT rolsuper FROM pg_roles WHERE rolname=current_user)
 OR (SELECT pg_get_userbyid(datdba) FROM pg_database WHERE datname=current_database())<>'postgres'
 THEN RAISE EXCEPTION 'IMPORT_DDL_EXECUTOR_PREIMAGE';END IF;
END $ddl_pre$;
CREATE TEMP TABLE import_ddl_edges ON COMMIT DROP AS
 SELECT roleid,member,grantor,admin_option,inherit_option,set_option FROM pg_auth_members
 WHERE roleid IN ('otr_trip_source_writer'::regrole) AND member='postgres'::regrole;
CREATE TEMP TABLE import_ddl_schema ON COMMIT DROP AS SELECT nspacl FROM pg_namespace WHERE nspname='public';
DO $edges$ DECLARE r text; BEGIN
 FOREACH r IN ARRAY ARRAY['otr_trip_source_writer'] LOOP
 IF has_schema_privilege(r,'public','CREATE') OR pg_has_role('postgres',r,'SET')
 OR (SELECT count(*) FROM pg_temp.import_ddl_edges WHERE roleid=r::regrole)<>2
 OR NOT EXISTS(SELECT 1 FROM pg_temp.import_ddl_edges WHERE roleid=r::regrole AND grantor='supabase_admin'::regrole AND admin_option AND NOT inherit_option AND NOT set_option)
 OR NOT EXISTS(SELECT 1 FROM pg_temp.import_ddl_edges WHERE roleid=r::regrole AND grantor='postgres'::regrole AND NOT admin_option AND NOT inherit_option AND NOT set_option)
 THEN RAISE EXCEPTION 'IMPORT_DDL_ROLE_EDGE_PREIMAGE';END IF;
 END LOOP;
END $edges$;
GRANT otr_trip_source_writer TO postgres WITH INHERIT FALSE,SET TRUE;
GRANT CREATE ON SCHEMA public TO otr_trip_source_writer;

SET LOCAL ROLE otr_trip_source_writer;

end:
RESET ROLE;
REVOKE CREATE ON SCHEMA public FROM otr_trip_source_writer;
GRANT otr_trip_source_writer TO postgres WITH INHERIT FALSE,SET FALSE;
DO $ddl_restore$ BEGIN
 IF EXISTS((SELECT roleid,member,grantor,admin_option,inherit_option,set_option FROM pg_auth_members WHERE roleid IN ('otr_trip_source_writer'::regrole) AND member='postgres'::regrole EXCEPT SELECT * FROM pg_temp.import_ddl_edges)
 UNION ALL (SELECT * FROM pg_temp.import_ddl_edges EXCEPT SELECT roleid,member,grantor,admin_option,inherit_option,set_option FROM pg_auth_members WHERE roleid IN ('otr_trip_source_writer'::regrole) AND member='postgres'::regrole))
 OR (SELECT nspacl FROM pg_namespace WHERE nspname='public') IS DISTINCT FROM (SELECT nspacl FROM pg_temp.import_ddl_schema)
 THEN RAISE EXCEPTION 'IMPORT_DDL_AUTHORITY_RESTORE_DRIFT';END IF;
END $ddl_restore$;
